cd /app/work && timeout 60 python3 -c "
from scipy.optimize import linprog
import numpy as np
for opts in [{'presolve': False}, {'primal_feasibility_tolerance':1e-10,'dual_feasibility_tolerance':1e-10,'ipm_optimality_tolerance':1e-12}, {'maxiter':100000}, {'bogus_key':1}]:
    try:
        r = linprog(np.array([1.0,1.0]), A_ub=np.array([[1.0,1.0]]), b_ub=np.array([2.0]), bounds=(0,None), method='highs', options=opts)
        print('OK', opts, r.status)
    except Exception as e:
        print('ERR', opts, type(e).__name__, e)
"
